insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('7e197df4-7903-5d3e-9683-a4aff5e11bfa', 'rg3-argument-evidence-p01', (select id from public.skills where slug = 'read-g3-argument-evidence'), null,
        '3-5', $q$Why Bread Dough Puffs Up$q$, $q$A ball of bread dough starts out small and heavy. A few hours later, it can be twice as big. How does that happen?

Most bread dough has a tiny living thing in it called yeast. One yeast is so small that you need a microscope to see it. Yeast eats sugar in the dough. As it eats, it gives off a gas.

Because the yeast keeps eating, it makes more and more gas. The gas forms tiny bubbles inside the dough. The dough is stretchy, so it holds the bubbles in, the way a balloon holds air.

As a result, the dough puffs up and grows bigger. Bakers often set the dough in a warm spot, because yeast works faster when it is warm.

Finally, the bread goes into a hot oven. The heat makes the bubbles grow a little more, and then the bread turns firm. When you cut a slice, you can see the tiny holes the bubbles left behind.$q$, 'draft')
