-- Passage rg3-argument-evidence-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('92617926-0ada-57d6-80a3-d487d6427ecc', 'rg3-argument-evidence-p02', (select id from public.skills where slug = 'read-g3-argument-evidence'), null,
        '3-5', $q$A New Life for Old Paper$q$, $q$When you drop a sheet of paper into a recycling bin, its trip is just beginning. Old paper can become new paper. It takes several steps.

First, a truck collects the paper and brings it to a recycling center. Workers sort it into piles. Newspaper goes in one pile, and cardboard goes in another.

Second, the sorted paper goes into a giant tub of water. A machine stirs the tub like a huge blender. The paper breaks apart into tiny bits. Soon it becomes a wet, gray mush called pulp.

Third, the pulp is cleaned. Screens catch staples, tape and bits of plastic. Soap and air bubbles lift the ink off. Because the ink is removed, the pulp turns lighter in color.

Next, the clean pulp is sprayed onto a long, flat screen. The water drains through the holes. Heavy rollers press the pulp flat, and hot rollers dry it.

Last, the dry paper is wound into giant rolls. Later, those rolls are cut into notebooks, boxes and paper towels. The paper you tossed away could come back to you!$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
